const text = v => !v ? "" : v.title ? v.title.map(t=>t.plain_text).join("") : v.rich_text ? v.rich_text.map(t=>t.plain_text).join("") : v.select ? (v.select.name||"") : "";
const out = [];
for (const it of $input.all().filter(i => i.json && i.json.id)) {
  const p = it.json, pr = p.properties || {};
  const get = re => { for (const k in pr) if (re.test(k)) return pr[k]; return null; };
  if (text(get(/^status$/i)) !== "Awaiting Approval") continue;
  let title = "";
  for (const k in pr) if (pr[k].type === "title") title = text(pr[k]);
  const draft = text(get(/^draft$/i)).replace(/\[estimate-json\][\s\S]*?\[\/estimate-json\]/gi, "").replace(/\[estimate-json\][\s\S]*$/gi, "").replace(/\s+/g, " ").trim();
  out.push({ id: p.id, title: title || "(untitled)", agent: text(get(/^agent$/i)), type: text(get(/^type$/i)),
    qa: text(get(/^qa result$/i)) || "Not checked", related_job: text(get(/^related job$/i)),
    created: p.created_time || "", preview: draft.slice(0, 160) });
}
out.sort((a, b) => String(a.created).localeCompare(String(b.created)));
return [{ json: { body: out.slice(0, 25) } }];
